<?php
declare(strict_types=1);require_once __DIR__.'/includes/functions.php';$s=db()->prepare('SELECT * FROM categories WHERE slug=? LIMIT 1');$s->execute([trim($_GET['slug']??'')]);$c=$s->fetch();if(!$c){http_response_code(404);exit('Категория не найдена.');}$s=db()->prepare("SELECT p.*,u.display_name author_name FROM posts p LEFT JOIN users u ON u.id=p.author_id WHERE p.category_id=? AND p.status='published' AND p.published_at<=NOW() ORDER BY p.published_at DESC");$s->execute([$c['id']]);$posts=$s->fetchAll();$pageTitle=$c['name'].' — '.APP_NAME;include __DIR__.'/includes/header.php';?><h1 class="category-heading"><?=e($c['name'])?></h1><section class="story-grid"><?php foreach($posts as $p):?><article class="news-card"><?php if($p['image_url']):?><img class="story-image" src="<?=e($p['image_url'])?>" alt="<?=e($p['title'])?>"><?php endif;?><h2><a href="<?=e(url('article.php?slug='.urlencode($p['slug'])))?>"><?=e($p['title'])?></a></h2><p><?=e($p['excerpt']?:excerpt($p['content']))?></p><div class="meta"><span><?=e($p['author_name']??'Редакция')?></span><span><?=e(format_date($p['published_at']))?></span></div></article><?php endforeach;?></section><?php if(!$posts):?><p>В этой рубрике пока нет материалов.</p><?php endif;?><?php include __DIR__.'/includes/footer.php';?>
